import { expect, test } from '@playwright/test';

/**
 * PB-PIPE-COMB-CORRECTION-001 — P3-B
 * Fabrication UI: optional section, workshop references, cut list, elbow
 * marking.
 *
 * Expected numbers are the FROZEN 3x35° acceptance fixture from the P3-A
 * review (Brain 6a47e94, head 39c95e3) — hand-transcribed from the reviewed
 * evidence, never generated by invoking the module under test:
 *   A = 253.169377 mm, t = 72.077303 mm,
 *   P1-IN 927.922697, P1-OUT 1127.922697, P2-IN 674.753320,
 *   P2-OUT 1191.912800, P3-IN 421.583943, P3-OUT 1255.902904 (mm).
 * Presentation format: formatLengthForUnit (mm 2 dec, in 4 dec, trailing
 * zeros trimmed, small positives auto-extended).
 */

const TOOL_URL = '/tools?t=pipe-comb&lng=en';
const TOOL_URL_ES = '/tools?t=pipe-comb&lng=es';

async function openTool(page: import('@playwright/test').Page, url: string = TOOL_URL) {
  await page.goto(url);
  const betaDialog = page.locator('div[role="dialog"][data-state="open"]');
  const shown = await betaDialog.waitFor({ state: 'visible', timeout: 10_000 }).then(() => true).catch(() => false);
  if (shown) {
    await betaDialog.getByRole('button', { name: /continuar|continue/i }).click();
    await betaDialog.waitFor({ state: 'hidden' });
  }
}

function setValues(page: import('@playwright/test').Page, values: Partial<Record<'count' | 'di' | 'df' | 'angle', string>>) {
  const map = {
    count: '#pipe-comb-pipe-count',
    di: '#pipe-comb-initial-spacing',
    df: '#pipe-comb-final-spacing',
    angle: '#pipe-comb-angle',
  } as const;
  return (async () => {
    for (const [key, selector] of Object.entries(map)) {
      const v = values[key as keyof typeof values];
      if (v === undefined) continue;
      await page.locator(selector).fill(v);
    }
  })();
}

/** Configure the complete 3x35° acceptance case (en, mm unless noted). */
async function setupCase3x35(page: import('@playwright/test').Page, url: string = TOOL_URL) {
  await openTool(page, url);
  await setValues(page, { count: '3', di: '250', df: '350', angle: '35' });
  await page.locator('[data-testid="pipe-comb-fab-toggle"]').click();
  await page.locator('#pipe-comb-fab-nps').selectOption('6');
  await page.locator('#pipe-comb-fab-lin').fill('1000');
  await page.locator('#pipe-comb-fab-lout').fill('1200');
}

function fabStatus(page: import('@playwright/test').Page) {
  return page.locator('[data-testid="pipe-comb-fab-status"]');
}

function fabMetric(page: import('@playwright/test').Page, key: string) {
  return page.locator(`[data-testid="pipe-comb-fab-metric"][data-metric="${key}"]`);
}

function pieceRow(page: import('@playwright/test').Page, id: string) {
  return page.locator(`[data-testid="pipe-comb-fab-piece"][data-piece-id="${id}"]`);
}

/* ------------------------------------------------------------------ *
 * 1. Optional section: P2 untouched
 * ------------------------------------------------------------------ */

test('fab-01: section is collapsed by default; P2 basic experience intact', async ({ page }) => {
  await openTool(page);
  const section = page.locator('[data-testid="pipe-comb-fab-section"]');
  await expect(section).toBeVisible();
  await expect(section).toHaveAttribute('data-open', 'false');
  await expect(page.locator('[data-testid="pipe-comb-fab-cutlist"]')).toHaveCount(0);
  /* P2 REF-01 defaults still work. */
  await expect(page.locator('[data-testid="pipe-comb-stagger-metric"][data-metric="cotaA"]')).toHaveText('365.69 mm');
});

test('fab-02: 3x35 complete case — summary, six pups, exact cut lengths', async ({ page }) => {
  await setupCase3x35(page);
  await expect(fabStatus(page)).toHaveAttribute('data-status', 'complete-warnings');
  await expect(fabStatus(page)).toHaveText('Calculation complete with warnings.');
  /* Summary: take-out t and stagger A stay visually distinct. */
  await expect(fabMetric(page, 'takeOut')).toHaveText('72.08 mm');
  await expect(fabMetric(page, 'stagger')).toHaveText('253.17 mm');
  /* Six straight pups correctly associated, elbows NOT in the cut list. */
  const pups = page.locator('[data-testid="pipe-comb-fab-piece"]');
  await expect(pups).toHaveCount(6);
  await expect(pieceRow(page, 'P1-IN').locator('td').nth(5)).toHaveText('927.92 mm');
  await expect(pieceRow(page, 'P1-OUT').locator('td').nth(5)).toHaveText('1127.92 mm');
  await expect(pieceRow(page, 'P2-IN').locator('td').nth(5)).toHaveText('674.75 mm');
  await expect(pieceRow(page, 'P2-OUT').locator('td').nth(5)).toHaveText('1191.91 mm');
  await expect(pieceRow(page, 'P3-IN').locator('td').nth(5)).toHaveText('421.58 mm');
  await expect(pieceRow(page, 'P3-OUT').locator('td').nth(5)).toHaveText('1255.9 mm');
  /* Elbows identified separately (3 catalog elbows cut to 35°). */
  const elbowsNote = page.locator('[data-testid="pipe-comb-fab-elbows"]');
  await expect(elbowsNote).toBeVisible();
  expect(await elbowsNote.textContent()).toContain('3');
  expect(await elbowsNote.textContent()).toContain('35');
});

