test('fab-09: weld gap and allowance applied once, no double discount', async ({ page }) => {
  await setupCase3x35(page);
  await page.locator('#pipe-comb-fab-gap').fill('2');
  await page.locator('#pipe-comb-fab-allowance').fill('50');
  await expect(fabStatus(page)).toHaveAttribute('data-status', 'complete-warnings');
  /* P1-IN: finished = 1000 - t - g = 925.922697; cut = +50 = 975.922697. */
  await expect(pieceRow(page, 'P1-IN').locator('td').nth(3)).toHaveText('925.92 mm');
  await expect(pieceRow(page, 'P1-IN').locator('td').nth(4)).toHaveText('50 mm');
  await expect(pieceRow(page, 'P1-IN').locator('td').nth(5)).toHaveText('975.92 mm');
  /* P2-IN cut = (1000 - A) - t - g + 50 = 722.753320 -> A deducted once. */
  await expect(pieceRow(page, 'P2-IN').locator('td').nth(5)).toHaveText('722.75 mm');
  /* The allowance is flagged as removed at fit-up in the detail. */
  const detail = page.locator('[data-testid="pipe-comb-fab-detail"][data-piece-id="P1-IN"]');
  await detail.locator('summary').click();
  expect(await detail.textContent()).toContain('Surplus of 50 mm');
});

