test('fab-25: mobile 320/390 — cards layout, no overflow, full cut values', async ({ page }) => {
  for (const width of [320, 390]) {
    await page.setViewportSize({ width, height: 800 });
    await setupCase3x35(page);
    /* Cards visible, desktop table hidden at this width. */
    await expect(page.locator('[data-testid="pipe-comb-fab-cutlist"] table')).toBeHidden();
    const card = page.locator('[data-testid="pipe-comb-fab-piece-card"][data-piece-id="P3-OUT"]');
    await expect(card).toBeVisible();
    /* The full cut value with unit is present and unclipped. */
    await expect(card).toContainText('1255.9 mm');
    const overflow = await page.evaluate(
      () => document.documentElement.scrollWidth - document.documentElement.clientWidth,
    );
    expect(overflow).toBeLessThanOrEqual(1);
  }
});

test('fab-26: English/inches presentation of the same case', async ({ page }) => {
  await setupCase3x35(page);
  await page.getByRole('button', { name: 'in', exact: true }).click();
  await expect(fabMetric(page, 'takeOut')).toHaveText('2.8377 in');
  await expect(fabMetric(page, 'stagger')).toHaveText('9.9673 in');
  await expect(pieceRow(page, 'P1-IN').locator('td').nth(5)).toHaveText('36.5324 in');
  await expect(pieceRow(page, 'P3-OUT').locator('td').nth(5)).toHaveText('49.445 in');
});

test('fab-27: N=12 renders a 24-piece cut list without page overflow', async ({ page }) => {
  await openTool(page);
  await setValues(page, { count: '12', di: '250', df: '350', angle: '35' });
  await page.locator('[data-testid="pipe-comb-fab-toggle"]').click();
  await page.locator('#pipe-comb-fab-nps').selectOption('6');
  await page.locator('#pipe-comb-fab-lin').fill('5000');
  await page.locator('#pipe-comb-fab-lout').fill('5000');
  await expect(page.locator('[data-testid="pipe-comb-fab-piece"]')).toHaveCount(24);
  await expect(pieceRow(page, 'P12-OUT')).toHaveCount(1);
  const overflow = await page.evaluate(
    () => document.documentElement.scrollWidth - document.documentElement.clientWidth,
  );
  expect(overflow).toBeLessThanOrEqual(1);
});

test('fab-28: negative stagger case keeps signed presentation', async ({ page }) => {
  /* REF-03-like geometry: Di 400 / Df 200 / 45 deg -> A = -117.16 mm. */
  await openTool(page);
  await setValues(page, { count: '3', di: '400', df: '200', angle: '45' });
  await page.locator('[data-testid="pipe-comb-fab-toggle"]').click();
  await page.locator('#pipe-comb-fab-nps').selectOption('6');
  await page.locator('#pipe-comb-fab-lin').fill('2000');
  await page.locator('#pipe-comb-fab-lout').fill('2000');
  await expect(fabStatus(page)).toHaveAttribute('data-status', 'complete-warnings');
  await expect(fabMetric(page, 'stagger')).toHaveText('-117.16 mm');
  /* Stagger A is ADDITIVE for a negative stagger: axis P2-IN =
     2000 + 117.157288 - t(45) 94.686986 = 2022.470301 mm. */
  await expect(pieceRow(page, 'P2-IN').locator('td').nth(5)).toHaveText('2022.47 mm');
});
